"""Bounded beam-search optimization for character-prefix-aware DataFrame reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Reorder rows and columns using bounded block-topology beam search."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the latest public row-specific orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert one scalar to evaluator text while preserving source values."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Score strings by the LCP sum of lexicographically adjacent strings."""
        if len(strings) < 2:
            return 0
        values = sorted(strings)
        total = 0
        previous = values[0]
        for value in values[1:]:
            total += len(value) if value == previous else cls._lcp(previous, value)
            previous = value
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column labels to their unique source positions."""
        result = {}
        for i, column in enumerate(columns):
            result.setdefault(str(column), []).append(i)
        return result

    @classmethod
    def _edges(cls, columns, dependencies, blocks):
        """Translate dependencies and merge blocks into directed index edges."""
        positions = cls._positions(columns)
        edges, seen = [], set()

        def add(left, right):
            """Add one nonredundant directed edge."""
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                edges.append((left, right))

        for pair in dependencies or []:
            if len(pair) == 2:
                left = positions.get(str(pair[0]), [])
                right = positions.get(str(pair[1]), [])
                if len(left) == 1 and len(right) == 1:
                    add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)
        return edges

    @classmethod
    def _constrained_order(cls, width, preference, columns, dependencies, blocks):
        """Topologically repair a preference while honoring supplied constraints."""
        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in cls._edges(columns, dependencies, blocks):
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {value: i for i, value in enumerate(preference)}
        queue = [
            (rank.get(i, width + i), i)
            for i in range(width)
            if indegree[i] == 0
        ]
        heapq.heapify(queue)

        result = []
        while queue:
            _, node = heapq.heappop(queue)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(queue, (rank.get(nxt, width + nxt), nxt))
        return result if len(result) == width else list(preference)

    @staticmethod
    def _stats(text):
        """Compute length-weighted pair repetition statistics per column."""
        rows, width = text.shape
        result = []
        for col in range(width):
            counts = {}
            for row in range(rows):
                value = text[row, col]
                counts[value] = counts.get(value, 0) + 1
            pair_mass = repeat_mass = total_mass = 0
            for value, count in counts.items():
                length = len(value)
                pair_mass += length * count * (count - 1)
                repeat_mass += length * max(0, count - 1)
                total_mass += length * count
            result.append((pair_mass, repeat_mass, total_mass))
        return result

    @staticmethod
    def _merge_blocks(width, columns, requested):
        """Construct atomic ordered blocks from valid merge requests."""
        parent = list(range(width))

        def find(value):
            """Find a disjoint-set root with path compression."""
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        positions = {}
        for i, column in enumerate(columns):
            positions.setdefault(str(column), []).append(i)

        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(group) for group in groups.values()), key=lambda x: x[0])

    @staticmethod
    def _affinity(text, left, right):
        """Measure length-weighted repeated right values conditioned on left values."""
        groups = {}
        for row in range(text.shape[0]):
            groups.setdefault(text[row, left], []).append(row)

        score = 0
        for row_group in groups.values():
            if len(row_group) < 2:
                continue
            counts = {}
            for row in row_group:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            for value, count in counts.items():
                score += len(value) * count * (count - 1)
        return score

    @classmethod
    def _block_candidates(cls, text, stats, blocks):
        """Generate at most two completed block paths with a width-four beam."""
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [sum(stats[col][0] for col in block) for block in blocks]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:32]
        active_set = frozenset(active)
        representatives = [block[:2] for block in blocks]

        # Cache every directed transition once; no affinity is recomputed in
        # the beam expansion itself.
        affinity = {}
        for left_block in active:
            for right_block in active:
                if left_block == right_block:
                    continue
                affinity[left_block, right_block] = sum(
                    cls._affinity(text, left, right)
                    for left in representatives[left_block]
                    for right in representatives[right_block]
                )

        beam = [
            ((seed,), active_set - {seed}, 0)
            for seed in active
        ]

        for _ in range(max(0, len(active) - 1)):
            expanded = []
            for path, remaining, value in beam:
                if not remaining:
                    expanded.append((path, remaining, value))
                    continue
                previous = path[-1]
                for successor in remaining:
                    expanded.append((
                        path + (successor,),
                        remaining - {successor},
                        value + affinity.get((previous, successor), 0),
                    ))

            if not expanded:
                break

            expanded.sort(
                key=lambda state: (
                    -state[2],
                    -sum(mass[i] for i in state[1]),
                    state[0],
                )
            )
            beam = expanded[:4]

        completed = []
        for path, remaining, value in beam:
            used = set(path)
            tail = sorted(
                (i for i in range(len(blocks)) if i not in used),
                key=lambda i: (-mass[i], blocks[i][0]),
            )
            completed.append((value, path + tuple(tail)))

        completed.sort(key=lambda item: (-item[0], item[1]))
        result, seen = [], set()
        for _, path in completed:
            flattened = tuple(
                column for block_index in path for column in blocks[block_index]
            )
            if flattened not in seen:
                seen.add(flattened)
                result.append(list(flattened))
            if len(result) == 2:
                break
        return result or [sum(blocks, [])]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every source row using its row-specific column order."""
        return [
            "".join(text[row, column] for column in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort rows by serialized keys and copy original cells without alteration."""
        row_order = sorted(
            range(source.shape[0]),
            key=lambda row: (serialized[row], row),
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            order = orders[source_row]
            values[output_row, :] = [source[source_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate a global order and two bounded beam-derived orders exactly."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for col in range(width):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        stats = self._stats(text)
        columns = list(df.columns)
        blocks = self._merge_blocks(width, columns, col_merge)

        baseline = [
            col for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [baseline]
        preferences.extend(self._block_candidates(text, stats, blocks))

        best_score = -1
        best_orders = None
        best_serialized = None

        for preference in preferences[:3]:
            repaired = self._constrained_order(
                width,
                preference,
                columns,
                one_way_dep,
                blocks,
            )
            orders = [repaired[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            score = self._trie_score(serialized)
            if score > best_score:
                best_score = score
                best_orders = orders
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

